#!/bin/bash
# Reproduction lab: time-triggered ZSK/KSK rollover under inline-signing.
set -euo pipefail

ROOT=/home/dev/feedback/uid38802
INST=$ROOT/artifacts/install
LAB=$ROOT/artifacts/lab
export LD_LIBRARY_PATH=$INST/lib
export PATH=$INST/sbin:$INST/bin:$PATH

ZONES="example.test example.org example.net"

cd "$LAB"
rm -rf zones keys run log conf
mkdir -p zones keys run log conf

# One shared HMAC secret for both the named control channel and rndc.
export LD_LIBRARY_PATH=$INST/lib
export PATH=$INST/sbin:$INST/bin:$PATH
tsig-keygen rndc-key | awk -F'"' '/secret/{print $2}' > run/rndc.secret

# dnssec-policy with short, test-friendly lifetimes and explicit ZSK + KSK.
cat > conf/policy.conf <<'EOF'
dnssec-policy "fastroll" {
	dnskey-ttl 60;
	max-zone-ttl 60;
	parent-ds-ttl 60;
	zone-propagation-delay 1;
	parent-propagation-delay 1;
	publish-safety 0;
	retire-safety 0;
	signatures-validity 300;
	signatures-refresh 240;
	signatures-jitter 0;
	keys {
		ksk key-directory lifetime 200 algorithm 13;
		zsk key-directory lifetime 200 algorithm 13;
	};
};
EOF

for z in $ZONES; do
	cat > zones/$z.db <<EOF
\$TTL 30
@   IN SOA ns1.$z. admin.$z. ( 1 30 30 60 30 )
@   IN NS  ns1.$z.
ns1 IN A   127.0.0.1
www IN A   127.0.0.2
EOF
done

cat > conf/named.conf <<EOF
include "$LAB/conf/policy.conf";

options {
	directory "$LAB";
	pid-file "$LAB/run/named.pid";
	listen-on port 5353 { 127.0.0.1; };
	listen-on-v6 { none; };
	recursion no;
	dnssec-validation no;
	managed-keys-directory "$LAB/run";
	session-keyfile "$LAB/run/session.key";
};
controls {
	inet 127.0.0.1 port 9553 allow { 127.0.0.1; }
		keys { rndc-key; };
};
key rndc-key {
	algorithm hmac-sha256;
	secret "$(cat "$LAB/run/rndc.secret")";
};
EOF

for z in $ZONES; do
	cat >> conf/named.conf <<EOF
zone "$z" {
	type primary;
	file "$LAB/zones/$z.db";
	inline-signing yes;
	dnssec-policy "fastroll";
	key-directory "$LAB/keys/$z";
};
EOF
	mkdir -p keys/$z
done

cat > conf/rndc.conf <<EOF
key rndc-key {
	algorithm hmac-sha256;
	secret "$(cat "$LAB/run/rndc.secret")";
};
options {
	default-key rndc-key;
	default-server 127.0.0.1;
	default-port 9553;
};
EOF

named-checkconf -t / conf/named.conf 2>/dev/null || named-checkconf conf/named.conf
echo "setup OK"

--- concurrent ---
#!/bin/bash
set -euo pipefail
ROOT=/home/dev/feedback/uid38802
INST=$ROOT/artifacts/install
LAB=$ROOT/artifacts/lab
export LD_LIBRARY_PATH=$INST/lib
DIG=$INST/bin/dig

cd "$LAB"
N=${1:-2000}
PAR=${2:-128}
find run -maxdepth 1 -name 'q-*' -delete 2>/dev/null || true

echo "firing $N +dnssec queries across 3 zones (parallelism $PAR)..."
seq 1 "$N" | xargs -P "$PAR" -I{} bash -c '
	i=$1
	z=$(printf "example.%s\n" test org net | sed -n "$((i % 3 + 1))p")
	'"$DIG"' +time=5 +tries=2 -p 5353 @127.0.0.1 "www.$z" A +dnssec \
		> "run/q-$i.out" 2>&1
' _ {}

total=$(find run -maxdepth 1 -name 'q-*.out' | wc -l)
nosig=0
servfail=0
for f in run/q-*.out; do
	if ! grep -q 'status: NOERROR' "$f"; then
		servfail=$((servfail + 1))
	# RRSIG covering the A rrset: line begins with owner and contains "RRSIG A"
	elif ! grep -Eq 'IN[[:space:]]+RRSIG[[:space:]]+A[[:space:]]' "$f"; then
		nosig=$((nosig + 1))
	fi
done

echo "total=$total servfail_or_timeout=$servfail missing_rrsig=$nosig"
if [ "$servfail" -eq 0 ] && [ "$nosig" -eq 0 ]; then
	echo "CONCURRENT-OK: every answer carried an RRSIG"
else
	echo "CONCURRENT-FAIL"
	exit 1
fi

--- acceptance ---
#!/bin/bash
# End-to-end acceptance for time-triggered ZSK/KSK rollover under
# inline-signing + dnssec-policy.
#
#   1. Start named cleanly with 3 inline-signed, dnssec-policy zones.
#   2. Wait until every zone has actually rolled both ZSK and KSK, and
#      observe the dual-write window (old + new key material coexisting).
#   3. Re-validate the full chain with delv for all 3 zones.
#   4. Fire a high-concurrency +dnssec workload and require zero missing
#      RRSIG and zero SERVFAIL/timeout.
set -euo pipefail

ROOT=/home/dev/feedback/uid38802
INST=$ROOT/artifacts/install
LAB=$ROOT/artifacts/lab
export LD_LIBRARY_PATH=$INST/lib
export PATH=$INST/sbin:$INST/bin:$PATH

ZONES="example.test example.org example.net"
WATCH=${WATCH:-300}          # seconds to wait for rollover

cd "$LAB"

echo "== [1/4] clean (re)start =="
if [ -f run/named.pid ] && kill -0 "$(cat run/named.pid)" 2>/dev/null; then
	rndc -c conf/rndc.conf halt >/dev/null 2>&1 || true
	sleep 1
fi
bash 00-setup.sh
setsid named -c "$LAB/conf/named.conf" -g < /dev/null \
	> "$LAB/log/named.run" 2>&1 &
echo $! > run/named.pid

for _ in $(seq 1 30); do
	if rndc -c conf/rndc.conf status >/dev/null 2>&1; then break; fi
	sleep 1
done
rndc -c conf/rndc.conf status >/dev/null
echo "named up, rndc control channel working"

echo "== [2/4] wait for real ZSK+KSK rollover (dual-write) =="
declare -A saw_successor
deadline=$((SECONDS + WATCH))
while [ "$SECONDS" -lt "$deadline" ]; do
	alldone=1
	for z in $ZONES; do
		# A successor key proves the policy created a replacement;
		# two simultaneously-active signers prove the dual-write
		# window rather than a hard cut-over.
		if grep -q '^Successor:' keys/$z/K*.state 2>/dev/null; then
			saw_successor[$z]=1
		fi
		[ "${saw_successor[$z]:-0}" = 1 ] || alldone=0
	done
	[ "$alldone" = 1 ] && break
	sleep 5
done

for z in $ZONES; do
	count=$(ls keys/$z/K*.key 2>/dev/null | wc -l)
	succ=$(grep -l '^Successor:' keys/$z/K*.state 2>/dev/null | wc -l)
	echo "  $z: key-files=$count states-with-successor=$succ"
	[ "${saw_successor[$z]:-0}" = 1 ] || {
		echo "FAIL: $z never produced a successor key within ${WATCH}s"
		exit 1
	}
done

# Show the dual-write evidence: more than one DNSKEY of each role is live.
for z in $ZONES; do
	ksk=$(dig +short -p 5353 @127.0.0.1 "$z" DNSKEY | awk '{print $1}' | grep -c 257 || true)
	zsk=$(dig +short -p 5353 @127.0.0.1 "$z" DNSKEY | awk '{print $1}' | grep -c 256 || true)
	echo "  $z live DNSKEYs: KSK(257)=$ksk ZSK(256)=$zsk"
done

echo "== [3/4] delv chain validation for all 3 zones =="
TA=run/trust-anchors.conf
echo "trust-anchors {" > "$TA"
for z in $ZONES; do
	kf=$(grep -l "DNSKEY.*257 " keys/$z/K*.key | head -1)
	rr=$(grep -v '^;' "$kf" | grep DNSKEY \
		| sed 's/^[^ ]* *[0-9]* *IN *DNSKEY *//' \
		| awk '{flags=$1; alg=$2; ft=$3; $1="";$2="";$3=""; b64=$0;
		         gsub(/^ +| +$/,"",b64);
		         printf "%s %s %s \"%s\"", flags, alg, ft, b64}')
	echo "	$z static-key $rr;" >> "$TA"
done
echo "};" >> "$TA"

for z in $ZONES; do
	res=$(delv -a "$TA" "+root=$z" -p 5353 @127.0.0.1 "www.$z" A 2>&1)
	echo "$res" | grep -q 'fully validated' || {
		echo "FAIL: delv did not validate $z"
		echo "$res" | tail -5
		exit 1
	}
	echo "  $z: fully validated"
done

echo "== [4/4] concurrent +dnssec workload =="
bash 03-concurrent.sh "${CONC_N:-2000}" "${CONC_PAR:-128}"

echo
echo "ACCEPTANCE-OK: time-triggered ZSK/KSK rollover, dual-write window,"
echo "intact validation chains on 3 zones, and zero missing signatures."

